const incoming = $input.first().json;
const body = incoming.body || incoming;
const inputPayload = body.input_payload || {};
const workflowDefinition = body.workflow_definition || {};
const taskId = body.task_id || inputPayload.task_id || '';
const title = body.title || inputPayload.title || 'Untitled video';
const horseName = body.horse_name || inputPayload.horse_name || inputPayload.horse || '';
const duration = Number(body.duration || inputPayload.duration || 30);
const aspectRatio = body.aspect_ratio || inputPayload.aspect_ratio || '9:16';
const callbackUrl = body.callback_url || incoming.callback_url || '';
const callbackToken = body.callback_token || incoming.callback_token || '';
const normalized = {
  task_id: taskId,
  title,
  horse_name: horseName,
  duration,
  aspect_ratio: aspectRatio,
  input_payload: inputPayload,
  workflow_definition: workflowDefinition,
  callback_url: callbackUrl,
  callback_token: callbackToken,
  source: body.source || 'baiqipu-video-factory'
};
return [{
  json: {
    ...normalized,
    normalized_payload: normalized,
    pipeline_version: 'video-factory-n8n-skeleton-v3',
    status: 'processing',
    progress: 12,
    current_node: 'script',
    node_states: [
      { node_id: 'input', status: 'completed', progress: 100, output: { title, horse_name: horseName, duration, aspect_ratio: aspectRatio } },
      { node_id: 'script', status: 'queued', progress: 0, output: {} },
      { node_id: 'storyboard', status: 'queued', progress: 0, output: {} },
      { node_id: 'veo', status: 'queued', progress: 0, output: {} },
      { node_id: 'voice', status: 'queued', progress: 0, output: {} },
      { node_id: 'subtitle', status: 'queued', progress: 0, output: {} },
      { node_id: 'compose', status: 'queued', progress: 0, output: {} },
      { node_id: 'output', status: 'queued', progress: 0, output: {} }
    ],
    result_payload: {
      pipeline_version: 'video-factory-n8n-skeleton-v3',
      normalized,
      next_required_api: 'script_or_storyboard_provider'
    }
  }
}];

const data = $input.first().json;
function upsert(states, next) {
  const copy = Array.isArray(states) ? states.map((state) => ({ ...state, output: { ...(state.output || {}) } })) : [];
  const index = copy.findIndex((state) => state.node_id === next.node_id);
  if (index >= 0) copy[index] = { ...copy[index], ...next, output: { ...(copy[index].output || {}), ...(next.output || {}) } };
  else copy.push(next);
  return copy;
}
const prompt = data.input_payload?.prompt || data.input_payload?.text || data.title;
const script = {
  title: data.title,
  logline: `${data.title} - ${data.horse_name || 'video subject'}`,
  narration: `Placeholder script for ${prompt}. Replace this Code node with the real script provider.`,
  tone: data.input_payload?.tone || 'cinematic',
  duration: data.duration
};
const node_states = upsert(data.node_states, { node_id: 'script', status: 'completed', progress: 100, output: { script } });
return [{ json: { ...data, script, node_states, progress: 24, current_node: 'storyboard', result_payload: { ...(data.result_payload || {}), script, next_required_api: 'storyboard_provider' } } }];

